import{_ as e,o as s,c as n,a2 as o}from"./chunks/framework.1C62pOns.js";const g=JSON.parse('{"title":"Manual de las pantallas","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/index.md","filePath":"es/interface/index.md","lastUpdated":1787856241000}'),r={name:"es/interface/index.md"};function t(i,a,l,d,c,p){return s(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="manual-de-las-pantallas" tabindex="-1">Manual de las pantallas <a class="header-anchor" href="#manual-de-las-pantallas" aria-label="Permalink to &quot;Manual de las pantallas&quot;">​</a></h1><p>Este manual no enumera campo por campo. Explica <strong>para qué sirve cada pantalla, qué decisiones te pide y dónde suele tropezar la gente</strong> — que es lo que no se adivina mirando la interfaz.</p><p>Las etiquetas de los campos las lees en la propia pantalla, y cambian de versión en versión; el motivo de cada decisión, no.</p><h2 id="recorrido" tabindex="-1">Recorrido <a class="header-anchor" href="#recorrido" aria-label="Permalink to &quot;Recorrido&quot;">​</a></h2><p>Si estás empezando, sigue este orden — cada pieza depende de la anterior:</p><ol><li><strong><a href="/pro-agent-hub-installer/es/interface/primeiros-passos">Primeros pasos</a></strong> — entrar, ubicarte en el menú, entender el panel.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/provedores-modelos">Proveedores y modelos</a></strong> — de dónde viene la inteligencia. Sin esto, nada más funciona.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/conhecimento">Conocimiento y fuentes de datos</a></strong> — lo que la plataforma sabe además del modelo.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/agentes">Agentes, equipos y chat</a></strong> — quién conversa y quién ejecuta.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/workflows">Workflows</a></strong> — automatización, visual o en código.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/planejadores">Planificadores</a></strong> — agentes que trabajan en ciclo hasta cumplir un objetivo.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/mcp">Servicios MCP</a></strong> — herramientas externas y las tuyas.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/apps">Apps</a></strong> — pantallas web construidas en la plataforma.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/integracoes">Integraciones</a></strong> — WhatsApp y Microsoft Teams.</li><li><strong><a href="/pro-agent-hub-installer/es/interface/administracao">Administración</a></strong> — grupos, usuarios, configuración, consumo y la copia de datos entre entornos.</li></ol><h2 id="lo-que-es-comun-a-todas-las-pantallas" tabindex="-1">Lo que es común a todas las pantallas <a class="header-anchor" href="#lo-que-es-comun-a-todas-las-pantallas" aria-label="Permalink to &quot;Lo que es común a todas las pantallas&quot;">​</a></h2><p><strong>Lista y detalle.</strong> Casi todo registro tiene una pantalla de lista, con búsqueda, y una de detalle, con pestañas. La lista trae un filtro <em>&quot;solo activos&quot;</em> — los registros deshabilitados siguen existiendo, solo salen del camino.</p><p><strong>Deshabilitar no es eliminar.</strong> Un registro deshabilitado deja de usarse pero conserva el historial y los vínculos. Eliminar es definitivo y suele rechazarse mientras haya algo apuntando a él.</p><p><strong>Guardar es explícito.</strong> Salir de una pantalla con cambios sin guardar dispara un aviso. Nada se graba hasta que confirmas.</p><p><strong>Lo que ves depende de tu grupo.</strong> Un usuario que no es master solo ve los agentes, equipos, workflows, planificadores, servicios MCP y Apps que alguno de sus grupos liberó — y con el modo que el grupo concedió: <em>lectura</em> permite abrir y ejecutar, <em>escritura</em> permite guardar. Ver <a href="/pro-agent-hub-installer/es/interface/administracao">Administración</a>.</p>',11)])])}const m=e(r,[["render",t]]);export{g as __pageData,m as default};
